"""Compile v0.4 source into the generic persistence snapshot without translating its science."""
from types import MappingProxyType
from solo_harness.studies.v04_types import CompiledStudy

def compile_v04(study):
    states=[{"id":x,"definition":x} for x in ("P","U","M","R","EA")]
    transitions=[{"id":x["id"],"from_state_id":x["from"],"target_state_id":x["to"],"target_kc_ids":x["components"],"target_relation_ids":x["relations"],"relevant_misconception_ids":x["misconceptions"],"state_order":{s["id"]:i for i,s in enumerate(states)}} for x in study.transitions["transitions"]]
    knowledge={"knowledge_components":[{"id":x["id"],"name":x["id"],"definition":x["claim"]} for x in study.knowledge["components"]],"relations":[{"id":x["id"],"name":x["id"],"definition":x["definition"],"kc_ids":[]} for x in study.knowledge["relations"]],"misconceptions":[{"id":x["id"],"name":x["id"],"definition":x["error"],"conflicts_with":[]} for x in study.knowledge["misconceptions"]],"solo_states":states,"transitions":transitions}
    pedagogies=[{"id":x["id"],"name":x["label"],"core_mechanism":x["mechanism"],"permissions":x["must"],"prohibitions":x["must_not"],"tutor_role":x["mechanism"],"prohibited_behavior":"; ".join(x["must_not"]),"treatment_fidelity_test":x["runtime_contract"]} for x in study.interventions["pedagogies"]]
    cells={}; moves={}; recipes={}
    for p in pedagogies: recipes[p["id"]]={"id":"v04-"+p["id"],"pedagogy_id":p["id"],"role_instruction":p["tutor_role"],"move_generation_instruction":study.prompts["TUTOR_PROMPT.md"],"learner_check_instruction":"Use the learner response.","completion_instruction":"Do not declare SOLO success.","prohibited_behavior":p["prohibitions"]}
    for x in study.interventions["cells"]:
        mid=x["id"]+":M1"; key=x["transition_id"]+":"+x["pedagogy_id"]
        cells[key]={"id":x["id"],"transition_id":x["transition_id"],"pedagogy_id":x["pedagogy_id"],"instructional_intent":x["scientific_goal"],"missing_structure":x["scientific_goal"],"target_kc_ids":[i for i in x["target_refs"] if i.startswith("K")],"target_relation_ids":[i for i in x["target_refs"] if i.startswith("R")],"relevant_misconception_ids":[],"move_ids":[mid],"prohibitions":[x["prohibition"]],"completion_condition":x["completion"],"treatment_constraints":x["fidelity_observation"],"max_tutor_turns":4}
        moves[mid]={"id":mid,"transition_id":x["transition_id"],"pedagogy_id":x["pedagogy_id"],"title":x["id"],"purpose":x["scientific_goal"],"kc_ids":cells[key]["target_kc_ids"],"relation_ids":cells[key]["target_relation_ids"],"misconception_ids":[],"material_blueprint":x["instructional_scenario"],"allowed_behavior":x["required_moves"],"prohibited_behavior":cells[key]["prohibitions"],"completion_evidence":x["completion"],"next_move_ids":[mid]}
    families={}; rubrics={}
    for t in transitions:
        forms=[]
        for b in [z for z in study.assessments["blueprints"] if z["transition_id"]==t["id"]]: forms.append({"id":b["id"],"title":b["title"],"task_type":"V04_FOUR_ITEM","generation_goal":b["blueprint_focus"],"scenario_seed":"typed policy","equivalence_constraints":[],"required_response_features":[],"misconception_probes":[],"prohibited_leakage":[],"target_kc_ids":[i for i in b["target_refs"] if i.startswith("K")],"target_relation_ids":[i for i in b["target_refs"] if i.startswith("R")],"target_evidence_ids":[],"relevant_misconception_ids":t["relevant_misconception_ids"],"v04_item_contracts":b["items"]})
        families[t["id"]]={"id":"v04-"+t["id"],"transition_id":t["id"],"forms":forms}; rubrics[t["id"]]={"id":"v04-"+t["id"],"transition_id":t["id"],"target_state_id":t["target_state_id"],"evidence_criteria":[],"success_rule":{"minimum_evidence":0}}
    authored={"manifest":{"study_id":study.study_id,"content_version":study.content_version,"study_schema_version":"v04-native-1","markdown_provenance":{}},"knowledge":knowledge,"pedagogies":pedagogies,"cells":list(cells.values()),"shared_intervention_envelope":{},"v04":{"source_hashes":study.source_hashes,"scientific":{"knowledge":study.knowledge,"transitions":study.transitions,"interventions":study.interventions,"assessments":study.assessments,"judge":study.judge,"protocol":study.protocol,"scenarios":study.scenarios,"prompts":study.prompts}}}
    slices={t["id"]:{"transition":t,"knowledge_components":[],"relations":[],"misconceptions":[]} for t in transitions}
    return CompiledStudy(study.study_id,f"{study.content_version}-native-2",authored,MappingProxyType(slices),MappingProxyType(cells),MappingProxyType(moves),MappingProxyType(recipes),MappingProxyType(families),MappingProxyType(rubrics),{"initial_state_id":"P","transition_ids":["C1","C2","C3","C4"],"pedagogy_ids":["P1","P2","P3"],"max_attempts_per_transition":3,"assessment_strategy":"random_unseen","pedagogy_strategy":"random_without_replacement"})
